function firdariaSequence(data){const lane=data.lanes.find((candidate)=>candidate.laneId==="firdaria_level_1");if(!lane||!lane.segments.length)return"";const cycle=lane.segments.filter((segment)=>segment.periodId.split(".")[0]===lane.segments[0].periodId.split(".")[0]);return cycle.map((segment)=>`${bodyName(segment.labelKey)} ${formatYears(segment.detail.end_year-segment.detail.start_year,0)}`).join("、");}
const SOURCES=Object.freeze({annual_profection:Object.freeze(["依古希臘占星家 Valens 的書《占星選集》（Anthologiae，第四卷第 11 章）：書裡用「第 35 年」舉例；我們對照希臘原文，那是滿 34 歲的那一年，和本站的數法相同。","古羅馬作家 Firmicus 的《Mathesis》（書名原意「學問」，第二卷第 27–28 章）也寫了這個方法；這一條依本站的研究筆記，還沒有重讀原書。","每一年從太陽回到出生時位置的那一刻算起；這個時刻由本站的星曆程式算出，測試另拿美國太空總署噴射推進實驗室（JPL）公開的星曆核對。",]),firdaria:Object.freeze(["al-Bīrūnī《占星術入門》（Kitāb al-Tafhīm）§438–439（Wright 英譯，1934）：期間表、日夜順序；交點不分子期。","Bonatti《天文學之書》（Decem tractatus astronomiae）Tr.9 Ch.3（Dykes 英譯）：各期年數、日盤順序、75 年後重來；夜盤「一切照日盤」。","Abū Maʿshar《論本命年的回歸》（Kitāb taḥāwīl sinī al-mawālīd；Dykes 英譯，Persian Nativities IV）：現存最完整的操作說明；本書未核。",]),firdariaNight:"夜盤兩個月交點排在火星之後，是 Zoller 對 Bonatti 的讀法，不是 Bonatti 的原文；本站預設排在水星之後。",zodiacal_releasing:Object.freeze(["Vettius Valens《占星選集》（Anthologiae）IV.4（起點、星座年數、小期、解鎖到對宮）、IV.7（從命運點數位置）、IV.8（例盤）、IV.9（分配年 360 日）、IV.10（更細的層級）：Riley 英譯，並對照 Kroll 的希臘文。","「黃道釋放」這個名稱與「第一層」「第二層」的分層名稱，是現代（Schmidt、Brennan）的整理，不是 Valens 的用語。",]),decennials:Object.freeze(["Vettius Valens《占星選集》（Anthologiae）VI.6–VI.7：每段 10 年 9 個月、依出生時的黃道順序、分配年 360 日；Riley 英譯。","Firmicus Maternus《Mathesis》II.26–27：日盤從太陽、夜盤從月亮起，每段再依小年分成月；拉丁文本。",]),monthly_profection:Object.freeze(["古希臘占星家 Valens 的《占星選集》（Anthologiae，第四卷第 28 章）：看此刻的太陽離出生時的太陽多遠，從年度小限的星座數同樣的距離，就是這個月；夜盤改用月亮，本站沒有採用。","中世紀占星家 Abū Maʿshar 的《論本命年的回歸》（Kitāb taḥāwīl sinī al-mawālīd）：年度小限的星座也是第 1 個月，太陽每多走 30 度換下一個月；我們只讀到英譯者 Dykes 的介紹，原書未核。","al-Bīrūnī 的《占星術入門》（Kitāb al-Tafhīm，第 522 節）：每個月從太陽走到出生時同一度數算起；同一節另有一年 13 個月的分法，本站沒有算。","Ptolemy 的《占星四書》（Tetrabiblos）第四卷第 10 章：每 28 天推一個星座，和太陽回歸對不齊，本站沒有算。",]),});const DECENNIALS_START_TEXT=Object.freeze({firmicus_sect_light_v1:"這次的起點是日盤從太陽、夜盤從月亮（Firmicus 的做法，本站預設）。",valens_first_after_asc_v1:"這次的起點是上升點之後的第一顆行星（Valens 在兩個光體都不合用時的做法；本站不判斷光體合不合用）。",user_selected_planet_v1:"這次的起點是你自己指定的行星。",});const EDITION_GLOSS="校勘本（學者比對多份古抄本後整理出的版本）";function verificationLine(head){const code=head&&head.source_verification;if(!code)return null;return`核對狀態：${(SOURCE_VERIFICATION[code]||code).replace("校勘本",EDITION_GLOSS)}`;}
